# yaml-language-server: $schema=../../schema/pack.schema.json
# Minimal starter pack. The message shape is illustrative and must be
# checked against real alerts (then rewritten as synthetic samples).
schema: 1
id: im_bank
name: I&M Bank
version: 0.1.0
currency: KES
utc_offset: "+03:00"
senders:
  - I&M
time_format: dd-MMM-yyyy HH:mm

rules:
